def distinct_in_window(nums, k):
    if k == 0 or k > len(nums):
        return []
    counts = {}
    result = []
    for i, value in enumerate(nums):
        counts[value] = counts.get(value, 0) + 1
        if i >= k:
            out = nums[i - k]
            counts[out] -= 1
            if counts[out] == 0:
                del counts[out]
        if i >= k - 1:
            result.append(len(counts))
    return result

