export function distinctInWindow(nums, k) {
  if (k === 0 || k > nums.length) return [];
  const counts = new Map();
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    counts.set(nums[i], (counts.get(nums[i]) ?? 0) + 1);
    if (i >= k) {
      const out = nums[i - k];
      const c = counts.get(out) - 1;
      if (c === 0) counts.delete(out);
      else counts.set(out, c);
    }
    if (i >= k - 1) result.push(counts.size);
  }
  return result;
}
